// ── LoopLeads: build HubSpot + Resend payloads ─────────────────────────
// Edit these four values for your accounts.
const FROM = 'LoopLeads <demo@loopleads.app>';      // must be a Resend-verified domain
const REPLY_TO = 'hello@loopleads.app';               // where prospects' replies go
const TEAM_TO = ['team@loopleads.app'];               // who gets the internal alert
const BRAND = { navy: '#121627', navy700: '#1C2333', orange: '#E07A40', canvas: '#F6F4EF', slate: '#38434F' };

const body = $('Webhook').first().json.body || {};
const lead = body.lead || {};
const src = body.source || {};
const utm = src.utm || {};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const planLabel = { light: 'LoopLeads Light', core: 'LoopLeads Core', unsure: 'Not sure yet' }[lead.plan] || 'Not sure yet';

const summary = [
  `Demo request from loopleads.app`,
  `Service type: ${lead.serviceType}`,
  `Interested in: ${planLabel}`,
  `Watched video: ${src.watchedVideo ? 'yes' : 'no'}`,
  `Marketing opt-in: ${lead.marketingOptIn ? 'yes' : 'no'}`,
  `UTM: ${['source','medium','campaign','term','content'].map(k => utm[k] ? `${k}=${utm[k]}` : '').filter(Boolean).join(', ') || 'none'}`,
  `Page: ${src.pageUrl || ''}`,
].join('\n');

const hubspot = {
  inputs: [{
    idProperty: 'email',
    id: lead.email,
    properties: {
      email: lead.email,
      firstname: lead.firstName,
      company: lead.businessName,
      phone: lead.phoneE164 || lead.phone,
      hs_lead_status: 'NEW',
      message: summary,
    },
  }],
};

const row = (k, v) => `<tr><td style="padding:6px 16px 6px 0;color:#5A6470;font-size:15px;white-space:nowrap">${k}</td><td style="padding:6px 0;font-size:15px;font-weight:700;color:${BRAND.navy}">${v}</td></tr>`;
const shell = (inner) => `<!doctype html><html><body style="margin:0;background:${BRAND.canvas};font-family:Arial,Helvetica,sans-serif;color:${BRAND.navy}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${BRAND.canvas};padding:32px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:10px;overflow:hidden">
<tr><td style="background:${BRAND.navy700};padding:22px 28px;font-size:22px;font-weight:800;letter-spacing:-0.5px"><span style="color:${BRAND.orange}">LOOP</span><span style="color:${BRAND.canvas}">LEADS</span></td></tr>
<tr><td style="padding:28px">${inner}</td></tr>
<tr><td style="padding:18px 28px;background:${BRAND.canvas};font-size:13px;color:#5A6470">LoopLeads — Every missed call deserves a second chance.</td></tr>
</table></td></tr></table></body></html>`;

const leadHtml = shell(`
<h1 style="margin:0 0 12px;font-size:24px;line-height:1.2">Thanks, ${esc(lead.firstName)}. Your demo request is in.</h1>
<p style="margin:0 0 16px;font-size:16px;line-height:1.6">We'll reach out by phone or email to set up a 5-minute demo for <strong>${esc(lead.businessName)}</strong>. Here's what we'll cover:</p>
<ol style="margin:0 0 20px;padding-left:20px;font-size:16px;line-height:1.6">
<li><strong>See the demo.</strong> A sample missed customer call, from the first ring to the owner email.</li>
<li><strong>Check your setup.</strong> Your business number, call routing, and the kinds of calls you get.</li>
<li><strong>Choose your starting point.</strong> If it's a fit, we'll explain the subscription, onboarding, and activation.</li>
</ol>
<p style="margin:0 0 6px;font-size:16px;line-height:1.6">No need to understand AI, automation, or complicated software. We'll show you the customer experience in plain English.</p>
<p style="margin:16px 0 0;font-size:16px;line-height:1.6">Questions before then? Just reply to this email.</p>`);

const teamHtml = shell(`
<div style="background:${BRAND.orange};color:${BRAND.navy};border-radius:6px 6px 0 0;padding:12px 16px;font-size:17px;font-weight:800">New demo request</div>
<table role="presentation" cellpadding="0" cellspacing="0" style="margin:12px 0 18px">
${row('Name', esc(lead.firstName))}
${row('Business', esc(lead.businessName))}
${row('Email', `<a href="mailto:${esc(lead.email)}" style="color:${BRAND.navy}">${esc(lead.email)}</a>`)}
${row('Phone', `<a href="tel:${esc(lead.phoneE164)}" style="color:${BRAND.navy}">${esc(lead.phone)}</a>`)}
${row('Service', esc(lead.serviceType))}
${row('Interested in', esc(planLabel))}
${row('Watched video', src.watchedVideo ? 'Yes' : 'No')}
${row('Marketing opt-in', lead.marketingOptIn ? 'Yes' : 'No')}
</table>
<p style="margin:0;font-size:13px;color:#5A6470;white-space:pre-line">${esc(summary)}</p>
<p style="margin:18px 0 0;font-size:15px"><strong>Next step:</strong> call ${esc(lead.firstName)} and book the 5-minute demo.</p>`);

return [{ json: {
  hubspot,
  leadEmail: { from: FROM, to: [lead.email], reply_to: REPLY_TO, subject: 'Your LoopLeads demo request', html: leadHtml, tags: [{ name: 'type', value: 'demo_confirmation' }] },
  teamEmail: { from: FROM, to: TEAM_TO, reply_to: lead.email, subject: `New demo request: ${lead.businessName} (${lead.serviceType})`, html: teamHtml, tags: [{ name: 'type', value: 'demo_internal_alert' }] },
} }];
